import React, { useEffect } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Header from './components/Header';
import Hero from './components/Hero';
import Products from './components/Products';
import Hangars from './components/Hangars';
import Tensile from './components/Tensile';
import Services from './components/Services';
import Contact from './components/Contact';
import Footer from './components/Footer';
import TentsPage from './components/TentsPage';
import HangarsPage from './components/HangarsPage';
import TensilePage from './components/TensilePage';
import './styles/globals.css';

const HomePage = () => (
  <>
    <Hero />
    <Products />
    <Hangars />
    <Tensile />
    <Services />
    <Contact />
  </>
);

function App() {
  useEffect(() => {
    document.body.style.backgroundImage = `
      url('${process.env.PUBLIC_URL}/background-img-1.jpg'),
      url('${process.env.PUBLIC_URL}/background-img-2.jpg'),
      url('${process.env.PUBLIC_URL}/background-img-3.jpg'),
      url('${process.env.PUBLIC_URL}/background-img-4.jpg')
    `;
    document.body.style.backgroundSize = '300px 200px, 250px 180px, 280px 190px, 320px 210px';
    document.body.style.backgroundPosition = '10% 20%, 80% 15%, 15% 70%, 85% 75%';
    document.body.style.backgroundRepeat = 'no-repeat';
    document.body.style.backgroundAttachment = 'fixed';
    document.body.style.opacity = '1';

    return () => {
      document.body.style.backgroundImage = '';
      document.body.style.backgroundSize = '';
      document.body.style.backgroundPosition = '';
      document.body.style.backgroundRepeat = '';
      document.body.style.backgroundAttachment = '';
    };
  }, []);

  return (
    <BrowserRouter>
      <div className="App">
        <Header />
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/tents" element={<TentsPage />} />
          <Route path="/hangars" element={<HangarsPage />} />
          <Route path="/tensile" element={<TensilePage />} />
        </Routes>
        <Footer />
      </div>
    </BrowserRouter>
  );
}

export default App;
